// Advanced custom hooks
import { useState, useCallback, useMemo, useRef, useTransition } from 'react';

// Debounced search hook
function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(timer);
  }, [value, delay]);

  return debouncedValue;
}

// Intersection observer hook
function useInView(ref: RefObject<HTMLElement>, options?: IntersectionObserverInit): boolean {
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      setInView(entry.isIntersecting);
    }, options);

    if (ref.current) observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref, options]);

  return inView;
}

// Usage in a component
function ProductSearch() {
  const [query, setQuery] = useState('');
  const [isPending, startTransition] = useTransition();
  const debouncedQuery = useDebounce(query, 300);
  const loadMoreRef = useRef<HTMLDivElement>(null);
  const isLoadMoreVisible = useInView(loadMoreRef);

  // Memoized filtered products
  const filteredProducts = useMemo(() =>
    products.filter(p =>
      p.name.toLowerCase().includes(debouncedQuery.toLowerCase())
    ),
    [debouncedQuery, products]
  );

  // Callback to avoid re-rendering child list
  const handleItemClick = useCallback((id: number) => {
    startTransition(() => {
      navigate(`/product/${id}`);
    });
  }, []);

  // Load more when sentinel element is visible
  useEffect(() => {
    if (isLoadMoreVisible) {
      loadMore();
    }
  }, [isLoadMoreVisible]);

  return (
    <div>
      <input
        value={query}
        onChange={e => setQuery(e.target.value)}
        placeholder="Search products..."
      />
      <ProductList
        products={filteredProducts}
        onItemClick={handleItemClick}
      />
      <div ref={loadMoreRef}>
        {isPending && <Spinner />}
      </div>
    </div>
  );
}
